+        side: THREE.DoubleSide,
+        transparent: false,
+        opacity: 1,
+        depthWrite: true,
+        toneMapped: false
+      });
+      material.userData.lockOpacity = true;
+      material.userData.explodedOpacity = 1;
+      return material;
+    }
+
+    function makeEdgeMaterial(depthTest = true) {
