+      // Clockwise winding for an ExtrudeGeometry hole.
+      hole.moveTo(x0, z0);
+      hole.lineTo(x0, z1);
+      hole.lineTo(x1, z1);
+      hole.lineTo(x1, z0);
+      hole.closePath();
+      shape.holes.push(hole);
+      return hole;
+    }
+
+    function addCircleHole(shape, centerX, centerZ, radius) {
+      const hole = new THREE.Path();
+      hole.absarc(centerX, centerZ, radius, 0, Math.PI * 2, true);
+      shape.holes.push(hole);
+      return hole;
+    }
